import anndata import scanpy as sc import pandas as pd import numpy as np import os import sys import warnings warnings.filterwarnings('ignore')
# Read input if '$input_type' == 'loom': adata = anndata.read_loom('$input_loom') elif '$input_type' == 'tabular': adata = anndata.read_csv('$input_csv', delimiter='$input_csv_delimiter') elif '$input_type' == 'mtx': adata = anndata.read_mtx('$input_mtx') elif '$input_type' == 'umi': adata = anndata.read_umi_tools('$input_umi', delimiter='$input_umi_delimiter') elif '$input_type' == '10x_h5': adata = sc.read_10x_h5('$input_10x_h5') elif '$input_type' == '10x_mtx': adata = sc.read_10x_mtx('$input_10x_mtx', var_names='gene_symbols') else: sys.exit('Input type not recognized')
# Write output adata.write_h5ad('$output_h5ad')
